// @generated by project-forge — visual-layout-diagrams.mjs (tree, erd, class, sequence clean-room layout engines)

import {
  displayWidth,
  expandLayoutBounds,
  kahnTopoSort,
  normalizeOrthogonalPoints,
  roundCoord,
  routeEdgesOrthogonal,
  roundedOrthogonalPath,
  truncateLabel,
} from './visual-router.mjs'

export const LEAF_STACK_THRESHOLD = 3

const measureTreeNodeWidth = (label, minW = 136, maxW = 220) => Math.max(minW, Math.min(maxW, 32 + displayWidth(truncateLabel(label, 24)) * 8))

/** Clean-Room 轮廓紧凑排布（contour packing）+ >=3 叶子节点垂直叠放列表。 */
export function layoutTreeDiagram(evidence, {
  nodeH = 40, leafH = 34, levelGapY = 54, nodeGapX = 24, leafGapY = 10, spineInset = 18, pad = 36,
} = {}) {
  const rootRaw = evidence?.root
  if (!rootRaw || typeof rootRaw !== 'object') {
    return { id: 'tree', kind: 'tree', width: 420, height: 260, nodes: [], edges: [], groups: [], meta: { stackedLeafGroups: 0, totalNodes: 0 } }
  }

  let seq = 0, stackedLeafGroups = 0
  const buildInternal = (raw, depth, parentId) => {
    const id = String(raw.path || raw.name || `node-${seq += 1}`).trim() || `node-${seq += 1}`
    const label = String(raw.name || raw.path || id).trim()
    const children = (Array.isArray(raw.children) ? raw.children : []).map((c) => buildInternal(c, depth + 1, id))
    const isLeaf = children.length === 0
    return {
      id, parentId, label, shortLabel: truncateLabel(label, 24), path: String(raw.path ?? ''),
      isFile: Boolean(raw.isFile), fileCount: Number(raw.fileCount) || (isLeaf ? 1 : 0),
      depth, w: measureTreeNodeWidth(label), h: isLeaf ? leafH : nodeH,
      children, isStackedLeaf: false, x: 0, y: 0,
    }
  }
  const root = buildInternal(rootRaw, 0, null)

  const shiftSubtree = (sub, dx, dy) => {
    sub.x = roundCoord(sub.x + dx); sub.y = roundCoord(sub.y + dy)
    for (const c of sub.children) shiftSubtree(c, dx, dy)
  }

  const packSubtree = (node) => {
    const leafKids = node.children.filter((c) => c.children.length === 0)
    const branchKids = node.children.filter((c) => c.children.length > 0)
    const stackLeaves = leafKids.length >= LEAF_STACK_THRESHOLD
    if (stackLeaves) stackedLeafGroups += 1
    if (node.children.length === 0) {
      node.x = 0; node.y = 0
      return { width: node.w, height: node.h, leftContour: [0], rightContour: [node.w] }
    }

    const childBlocks = [], childTopY = node.h + levelGapY
    if (stackLeaves) {
      const colW = Math.max(...leafKids.map((c) => c.w))
      let curY = childTopY
      for (const lf of leafKids) {
        lf.isStackedLeaf = true; lf.w = colW; lf.h = leafH; lf.x = spineInset; lf.y = curY
        curY += leafH + leafGapY
      }
      const stackH = curY - leafGapY
      const span = Math.max(1, Math.ceil((stackH - childTopY) / (nodeH + levelGapY)))
      childBlocks.push({
        kind: 'leaf-stack', leaves: leafKids, spineX: 0, maxY: stackH,
        leftContour: Array.from({ length: span + 1 }, () => 0),
        rightContour: Array.from({ length: span + 1 }, () => spineInset + colW),
      })
    }

    for (const kid of stackLeaves ? branchKids : node.children) {
      const m = packSubtree(kid)
      shiftSubtree(kid, 0, childTopY)
      childBlocks.push({ kind: 'subtree', node: kid, maxY: childTopY + m.height, leftContour: m.leftContour, rightContour: m.rightContour })
    }

    const mergedLeft = [...childBlocks[0].leftContour], mergedRight = [...childBlocks[0].rightContour]
    let totalMaxY = childBlocks[0].maxY
    for (let i = 1; i < childBlocks.length; i += 1) {
      const blk = childBlocks[i], sharedDepth = Math.min(mergedRight.length, blk.leftContour.length)
      let shift = 0
      for (let d = 0; d < sharedDepth; d += 1) shift = Math.max(shift, mergedRight[d] + nodeGapX - blk.leftContour[d])
      shift = roundCoord(shift)
      if (blk.kind === 'leaf-stack') { blk.spineX = roundCoord(blk.spineX + shift); for (const lf of blk.leaves) lf.x = roundCoord(lf.x + shift) }
      else shiftSubtree(blk.node, shift, 0)
      for (let d = 0; d < blk.rightContour.length; d += 1) {
        const rVal = roundCoord(blk.rightContour[d] + shift), lVal = roundCoord(blk.leftContour[d] + shift)
        if (d < mergedRight.length) { mergedRight[d] = Math.max(mergedRight[d], rVal); mergedLeft[d] = Math.min(mergedLeft[d], lVal) }
        else { mergedRight.push(rVal); mergedLeft.push(lVal) }
      }
      if (blk.maxY > totalMaxY) totalMaxY = blk.maxY
    }

    const cLeft = Math.min(...mergedLeft), cRight = Math.max(...mergedRight)
    const rootX = roundCoord(cLeft + ((cRight - cLeft) - node.w) / 2)
    const normShift = rootX < 0 ? roundCoord(-rootX) : 0
    node.x = roundCoord(rootX + normShift); node.y = 0
    if (normShift > 0) {
      for (const blk of childBlocks) {
        if (blk.kind === 'leaf-stack') { blk.spineX = roundCoord(blk.spineX + normShift); for (const lf of blk.leaves) lf.x = roundCoord(lf.x + normShift) }
        else shiftSubtree(blk.node, normShift, 0)
      }
    }
    const finalLeft = [node.x, ...mergedLeft.map((v) => roundCoord(v + normShift))]
    const finalRight = [roundCoord(node.x + node.w), ...mergedRight.map((v) => roundCoord(v + normShift))]
    return { width: Math.max(...finalRight), height: totalMaxY, leftContour: finalLeft, rightContour: finalRight }
  }

  packSubtree(root)
  shiftSubtree(root, pad, pad)

  const nodes = [], edges = []
  const collect = (n) => {
    const cx = roundCoord(n.x + n.w / 2), cy = roundCoord(n.y + n.h / 2)
    nodes.push({ id: n.id, parentId: n.parentId, label: n.label, shortLabel: n.shortLabel, path: n.path, isFile: n.isFile, isStackedLeaf: n.isStackedLeaf, fileCount: n.fileCount, depth: n.depth, x: n.x, y: n.y, w: n.w, h: n.h, cx, cy })
    const barY = roundCoord(n.y + n.h + Math.min(22, levelGapY / 2)), pBottom = { x: cx, y: roundCoord(n.y + n.h) }
    for (const c of n.children) {
      const pts = c.isStackedLeaf
        ? normalizeOrthogonalPoints([pBottom, { x: pBottom.x, y: barY }, { x: roundCoord(c.x - spineInset + 4), y: barY }, { x: roundCoord(c.x - spineInset + 4), y: roundCoord(c.y + c.h / 2) }, { x: c.x, y: roundCoord(c.y + c.h / 2) }])
        : normalizeOrthogonalPoints([pBottom, { x: pBottom.x, y: barY }, { x: roundCoord(c.x + c.w / 2), y: barY }, { x: roundCoord(c.x + c.w / 2), y: c.y }])
      edges.push({ id: `${n.id}->${c.id}`, fromId: n.id, toId: c.id, points: pts, pathD: roundedOrthogonalPath(pts, 8) })
      collect(c)
    }
  }
  collect(root)

  const dims = expandLayoutBounds(nodes, edges, [], pad)
  return { id: 'tree', kind: 'tree', width: dims.width, height: dims.height, nodes, edges, groups: [], meta: { stackedLeafGroups, totalNodes: nodes.length } }
}

/** ERD 分层实体网格布局：按外键引用分层，字段数决定卡片高度，调用 visual-router 避障路由。 */
export function layoutErdDiagram(evidence, {
  cardW = 228, headerH = 38, rowH = 22, cardPadBottom = 12, gapX = 64, gapY = 64, pad = 40,
} = {}) {
  const entities = Array.isArray(evidence?.entities) ? evidence.entities : []
  const relations = Array.isArray(evidence?.relations) ? evidence.relations : []
  if (entities.length === 0) {
    return { id: 'erd', kind: 'erd', width: 420, height: 260, nodes: [], edges: [], groups: [], meta: { entityCount: 0 } }
  }

  const entMap = new Map()
  for (const e of entities) {
    const name = String(e?.name || '').trim()
    if (name) entMap.set(name, { id: name, label: name, shortLabel: truncateLabel(name, 22), source: String(e.source || ''), fields: Array.isArray(e.fields) ? e.fields.map(String) : [] })
  }
  const ids = [...entMap.keys()].sort()
  const pairs = relations.filter((r) => entMap.has(r.from) && entMap.has(r.to) && r.from !== r.to).map((r) => [r.to, r.from])
  const { rank } = kahnTopoSort(ids, pairs, (a, b) => a.localeCompare(b))
  const byTier = new Map()
  for (const id of ids) {
    const t = rank.get(id) || 0
    if (!byTier.has(t)) byTier.set(t, [])
    byTier.get(t).push(entMap.get(id))
  }

  const nodes = [], boxMap = new Map()
  let curY = pad
  for (const t of [...byTier.keys()].sort((a, b) => a - b)) {
    const rowItems = byTier.get(t).sort((a, b) => a.id.localeCompare(b.id))
    let maxH = 0
    rowItems.forEach((ent, colIdx) => {
      const visibleFields = ent.fields.slice(0, 12), extraFieldCount = Math.max(0, ent.fields.length - visibleFields.length)
      const h = headerH + Math.max(1, visibleFields.length + (extraFieldCount > 0 ? 1 : 0)) * rowH + cardPadBottom
      const x = pad + colIdx * (cardW + gapX), y = curY
      const node = { ...ent, visibleFields, extraFieldCount, tier: t, x, y, w: cardW, h, cx: roundCoord(x + cardW / 2), cy: roundCoord(y + h / 2) }
      nodes.push(node); boxMap.set(node.id, node)
      if (h > maxH) maxH = h
    })
    curY += maxH + gapY
  }

  const rawEdges = relations.filter((r) => boxMap.has(r.from) && boxMap.has(r.to) && r.from !== r.to).map((r, idx) => {
    const hasMany = entMap.get(r.to)?.fields?.some((f) => f.includes('[]')) || r.cardinality === '1:N'
    return { id: `erd:${r.from}->${r.to}:${idx}`, fromId: r.from, toId: r.to, label: String(r.label || 'fk'), cardinality: r.cardinality === '1:1' ? '1:1' : (hasMany || r.label ? '1:N' : '1:1') }
  })
  const { edges } = routeEdgesOrthogonal(rawEdges, boxMap, nodes, { clearance: 14, pad: 16 })
  for (const e of edges) {
    const mid = e.points[Math.floor(e.points.length / 2)] || e.points[0]
    e.labelX = roundCoord(mid?.x ?? 0); e.labelY = roundCoord((mid?.y ?? 0) - 8)
  }
  const dims = expandLayoutBounds(nodes, edges, [], pad)
  return { id: 'erd', kind: 'erd', width: dims.width, height: dims.height, nodes, edges, groups: [], meta: { entityCount: nodes.length, relationCount: edges.length } }
}

/** Class 拓扑分层 + 半列步进（half-col）水平交错布局。 */
export function layoutClassDiagram(evidence, {
  cardW = 200, cardH = 66, gapX = 56, gapY = 72, pad = 44,
} = {}) {
  const rawEdges = Array.isArray(evidence?.edges) ? evidence.edges : []
  const nameSet = new Set(Array.isArray(evidence?.classes) ? evidence.classes : [])
  for (const e of rawEdges) { if (e?.from) nameSet.add(e.from); if (e?.to) nameSet.add(e.to) }
  const ids = [...nameSet].sort()
  if (ids.length === 0) {
    return { id: 'class', kind: 'class', width: 420, height: 260, nodes: [], edges: [], groups: [], meta: { halfColStaggered: false } }
  }

  const pairs = rawEdges.filter((e) => e?.from && e?.to && e.from !== e.to).map((e) => [e.to, e.from])
  const { rank } = kahnTopoSort(ids, pairs, (a, b) => a.localeCompare(b))
  const byLayer = new Map()
  for (const id of ids) {
    const r = rank.get(id) || 0
    if (!byLayer.has(r)) byLayer.set(r, [])
    byLayer.get(r).push(id)
  }

  const layers = [...byLayer.keys()].sort((a, b) => a - b), halfStep = roundCoord((cardW + gapX) / 2)
  const nodes = [], boxMap = new Map()
  let halfColStaggered = false
  for (const layer of layers) {
    const group = byLayer.get(layer).sort(), isOdd = layer % 2 === 1
    if (isOdd && group.length > 0) halfColStaggered = true
    const rowOffsetX = pad + (isOdd ? halfStep : 0), y = pad + layer * (cardH + gapY)
    group.forEach((cls, idx) => {
      const x = roundCoord(rowOffsetX + idx * (cardW + gapX))
      const node = { id: cls, label: cls, shortLabel: truncateLabel(cls, 22), layer, staggered: isOdd, x, y, w: cardW, h: cardH, cx: roundCoord(x + cardW / 2), cy: roundCoord(y + cardH / 2) }
      nodes.push(node); boxMap.set(cls, node)
    })
  }

  const styleMap = {
    extends: { lineStyle: 'solid', marker: 'hollow-triangle' },
    implements: { lineStyle: 'dashed', marker: 'hollow-triangle' },
    embeds: { lineStyle: 'dotted', marker: 'hollow-diamond' },
  }
  const edgeInputs = rawEdges.filter((e) => boxMap.has(e.from) && boxMap.has(e.to) && e.from !== e.to).map((e, idx) => {
    const kind = String(e.kind || 'extends'), st = styleMap[kind] || styleMap.extends
    return { id: `cls:${e.from}->${e.to}:${kind}:${idx}`, fromId: e.from, toId: e.to, kind, lineStyle: st.lineStyle, marker: st.marker, outSide: 'top', inSide: 'bottom' }
  })
  const { edges } = routeEdgesOrthogonal(edgeInputs, boxMap, nodes, { clearance: 14, pad: 16 })
  const dims = expandLayoutBounds(nodes, edges, [], pad)
  return { id: 'class', kind: 'class', width: dims.width, height: dims.height, nodes, edges, groups: [], meta: { halfColStaggered, layerCount: layers.length } }
}

/** Sequence 参与者生命线与严格递增消息序列布局。 */
export function layoutSequenceDiagram(evidence, {
  headW = 168, headH = 44, colGap = 48, firstMsgGap = 44, rowH = 48, selfLoopW = 46, selfLoopH = 22, pad = 36,
} = {}) {
  const steps = Array.isArray(evidence?.steps) ? evidence.steps : []
  const partOrder = [], seen = new Set()
  const addPart = (p) => { const id = String(p || '').trim(); if (id && !seen.has(id)) { seen.add(id); partOrder.push(id) } }
  for (const p of Array.isArray(evidence?.participants) ? evidence.participants : []) addPart(p)
  for (const s of steps) { addPart(s?.from); addPart(s?.to) }
  if (partOrder.length === 0) {
    return { id: 'sequence', kind: 'sequence', width: 420, height: 260, nodes: [], edges: [], lifelines: [], messages: [], groups: [], meta: { messageCount: 0 } }
  }

  const nodes = [], partMap = new Map()
  partOrder.forEach((pid, idx) => {
    const shortName = pid.includes('/') ? pid.split('/').pop() : pid, x = roundCoord(pad + idx * (headW + colGap)), y = pad
    const box = { id: pid, label: pid, shortLabel: truncateLabel(shortName, 18), index: idx, x, y, w: headW, h: headH, cx: roundCoord(x + headW / 2), cy: roundCoord(y + headH / 2) }
    nodes.push(box); partMap.set(pid, box)
  })

  const messages = [], edges = []
  let curY = pad + headH + firstMsgGap
  steps.forEach((s, idx) => {
    const src = partMap.get(s.from), dst = partMap.get(s.to)
    if (!src || !dst) return
    const isSelfCall = src.id === dst.id, y = roundCoord(curY)
    const label = truncateLabel(String(s.label || s.action || `hop ${s.hop ?? idx + 1}`).trim(), 28)
    const pts = isSelfCall
      ? normalizeOrthogonalPoints([{ x: src.cx, y }, { x: roundCoord(src.cx + selfLoopW), y }, { x: roundCoord(src.cx + selfLoopW), y: roundCoord(y + selfLoopH) }, { x: src.cx, y: roundCoord(y + selfLoopH) }])
      : normalizeOrthogonalPoints([{ x: src.cx, y }, { x: dst.cx, y }])
    const labelX = isSelfCall ? roundCoord(src.cx + selfLoopW + 6) : roundCoord((src.cx + dst.cx) / 2)
    const labelY = isSelfCall ? roundCoord(y + selfLoopH / 2) : roundCoord(y - 10)
    curY += isSelfCall ? (rowH + selfLoopH) : rowH
    const edgeId = `seq:${idx + 1}:${src.id}->${dst.id}`, pathD = roundedOrthogonalPath(pts, 6)
    messages.push({ id: edgeId, hop: s.hop ?? idx + 1, fromId: src.id, toId: dst.id, label, y, isSelfCall, labelX, labelY, points: pts, pathD })
    edges.push({ id: edgeId, fromId: src.id, toId: dst.id, label, isSelfCall, labelX, labelY, points: pts, pathD })
  })

  const lifelineBottomY = roundCoord(Math.max(pad + headH + 80, curY + 12))
  const lifelines = nodes.map((n) => ({ participantId: n.id, x: n.cx, y1: roundCoord(n.y + n.h), y2: lifelineBottomY }))
  const dims = expandLayoutBounds(nodes, edges, [], pad)
  return { id: 'sequence', kind: 'sequence', width: dims.width, height: Math.max(dims.height, roundCoord(lifelineBottomY + pad)), nodes, edges, lifelines, messages, groups: [], meta: { participantCount: nodes.length, messageCount: messages.length } }
}
